import { Application, ApplicationOptions } from 'pixi.js';
import { defineComponent } from 'vue';

import { AssetManager, IAssetConfig } from '@game-studio/asset-manager';

import { HowToPlayManagerLegacy, HowToPlaySlideLegacy } from '../../../components/slider';
import { gameConfig } from '../../../models/config-model';
import { inversifyContainer } from '../../../inversify/container';
import { loggingModel } from '../../../models/logging';
import { eventEmitter } from '../../../services/event-emitter';
import { IStrings } from '../../../types';
import { countHTPSlides } from '../slide-counter';
import { queryStringParams } from '../../../services/query-string';

export default defineComponent({
    name: 'HowToPlayDesktop',
    components: {
    },
    data() {
        return {
            closeBtnImagePath: '',
            cdnUrl: '',
            skin: '',
            version: '',
            app: undefined as Application | undefined,
            howToPlayAnimations: null as HowToPlayManagerLegacy | null
        };
    },
    computed: {
        strings(): IStrings {
            return inversifyContainer.strings;
        }
    },
    beforeMount(): void {
        if (!loggingModel.hasViewedHTP) {
            loggingModel.hasViewedHTP = true;
            loggingModel.logMetrics({ HTP_VIEWED: true });
        }
    },
    mounted(): void {
        const coreAssetVersion = inversifyContainer.adminSettings.assetVersion.core;
        const assetsBaseUrl = (inversifyContainer.skin.dataList as IAssetConfig).baseUrl;
        const localAssetFilePath = assetsBaseUrl + 'core/how-to-play/';
        const coreAssetFilePath = assetsBaseUrl + 'core/' + coreAssetVersion + '/how-to-play/';
        this.closeBtnImagePath = gameConfig.features.usingLocalAssets ? localAssetFilePath : coreAssetFilePath;

        const pixiOptions: Partial<ApplicationOptions> = {
            backgroundColor: 0xffffff,
            preserveDrawingBuffer: true,
            width: (this.$refs.htpContainer as HTMLElement).clientWidth,
            height: (this.$refs.htpContainer as HTMLElement).clientHeight,
            view: this.$refs.howToPlay as HTMLCanvasElement,
            resolution: window.devicePixelRatio
        };

        const slidesArray: HowToPlaySlideLegacy[] = [];
        const slideCount = countHTPSlides();

        for (let i = 0; i < slideCount; i++) {
            const assetName = 'how-to-play-slide-' + (i + 1);
            const text = this.strings.howToPlay.slides[i] as string;
            if (typeof text !== 'string') {
                console.error(`Invalid htp strings in howToPlay.slides: For the legacy HTP design howToPlay.slides should be an array of strings. Index ${i} is invalid`);
            }
            slidesArray.push(new HowToPlaySlideLegacy(AssetManager.getSpineData(assetName), text));
        }

        this.app = new Application(pixiOptions);
        this.howToPlayAnimations = new HowToPlayManagerLegacy(
            slidesArray,
            {
                enabled: AssetManager.getTexture('slider-dark-dot'),
                disabled: AssetManager.getTexture('slider-light-dot')
            },
            {
                width: this.app.view.clientWidth,
                height: this.app.view.clientHeight
            },
            queryStringParams.locale
        );

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        this.app.stage.addChild(this.howToPlayAnimations as any);
        this.app.ticker.speed = 0.5; // Sets the ticker to run at 30fps max
        this.app.ticker.start();
        this.app.render();
    },
    beforeDestroy(): void {
        this.app?.destroy();
        delete this.app;
    },
    methods: {
        toggle(): void {
            eventEmitter.emit('POPUP_TOGGLE_OLD_HTP', false); 
        },
        getBuildVersion(): string {
            return 'v' + gameConfig.version;
        },
        getCloseButtonImageURL(): string {
            return `${this.closeBtnImagePath}teal-cross.png`;
        }
    }
});
